\label{thm:PRDS_multidim}
For any family of scores $(S_{k+1},\dots,S_{n+m})$ satisfying Assumptions~\ref{as:newexch}~and~\ref{as:noties}, the empirical $p$-values defined in \eqref{emppvalues} are PRDS on $\cH_0$ and the null $p$-values are super-uniform.
In particular, under Assumptions~\ref{as:exchangeable0}~and~\ref{as:noties}, this result holds for the $p$-values generated by AdaDetect with a score function satisfying \eqref{constrainedg}.

\label{thm:FDRBONuS}
Consider any family of scores $(S_{k+1},\dots,S_{n+m})$ satisfying Assumptions~\ref{as:newexch}~and~\ref{as:noties}. Let $R_\alpha$ denote the rejection set of BH procedure applied to $p$-values defined in \eqref{emppvalues} at level $\alpha$. Then, for any distribution $P\in \mathcal{P}$,
\begin{align}\label{equnew}
\FDR(P,R_\alpha)=  \sum_{i\in \cH_0}  \E\left(\frac{ \lfloor \alpha (\l+1)K_i/m\rfloor }{(\ell +1) K_i}\right),
\end{align}
where $K_i$ is a random variable that takes values in $\{1,\dots,m\}$ for any $i \in \cH_0$. In particular, under Assumptions~\ref{as:exchangeable0}~and~\ref{as:noties}, \eqref{equnew} holds with $R_\alpha=\mbox{AdaDetect}_{\alpha}$, the AdaDetect procedure at level $\alpha$.

\label{thm:AdaptBONuS}
In the setting of Theorem~\ref{thm:FDRBONuS}, denote $p=(p_i,1\leq i\leq m)$ the family of empirical $p$-values defined in \eqref{emppvalues} and consider any function $G : [0,1]^m \rightarrow (0,\infty)$ that is coordinate-wise nondecreasing. Then the procedure, denoted by $R_{\alpha m/G(p)}$, combining the BH algorithm  at level $\alpha m/G(p)$ with these empirical $p$-values is such that, for any parameter $P\in \mathcal{P}$,
\begin{equation}\label{equboundsadaptive}
\FDR(P,R_{\alpha m/G(p) }) \leq  \alpha \sum_{i\in \cH_0}  \E_{p'\sim \mathcal{D}_i}\left(\frac{1}{G(p')} \right),
\end{equation}
where $\mathcal{D}_{i}$ is defined by \eqref{def:Di}. In particular, this FDR expression holds for $R_{\alpha m/G(p) }=\mbox{AdaDetect}_{{\alpha m/G(p) }}$ 
under Assumptions~\ref{as:exchangeable0}~and~\ref{as:noties}.

\label{powerhighdim}
Consider the setting of Theorem \ref{th:SCextended}. Assume $\alpha, \beta\in (0,1)$, $k,m_1\geq 1$, and $g^\sharp_\cG$, defined in \eqref{equNP}, satisfies $R_0(g^\sharp_\cG) = \beta$. Fix any $\delta\in (0,1/2)$. 
Then there exist constants $C,C'>0$ that only depend on $\delta$ such that, if 
\begin{equation}\label{equDelta}
\epsilon_0 = C\sqrt{\frac{V(\cG) + \log(1/\delta)}{k}}, \quad \Delta = C' \gamma^{-1} \sqrt{\frac{V(\cG) + \log(1/\delta)}{k\wedge \ell}},
\end{equation}
where $\gamma$ is defined in \eqref{equfgamma},  the following results hold.
\begin{itemize}
\item[(i)]
With probability at least $1-\delta$, 
$
{R}_0(\hat{g})  \leq \beta + \Delta
$
and
$
{R}_1(\hat{g}) \leq {R}_1(g^\sharp_\cG) + \Delta.
$
\item[(ii)] Let $M = \lceil (1-{R}_1(g^\sharp_\cG)-\Delta) m_1\rceil$. Assume that
 \begin{equation}\label{equlconstraint}
\rev{1-{R}_1(g^\sharp_\cG)  \geq  (1+\alpha^{-1})  \Delta, \quad \ell\geq \frac{2 m}{\alpha M}, \quad \beta \le \frac{0.4\alpha M}{m}. }
\end{equation}
Then, with probability at least $1-\delta$,
\begin{align}
\mbox{AdaDetect}_\alpha &\supset \{i\in \{1,\dots,m\}\::\: \hat{g}(X_i)\geq 0\}\label{rejectsalot},\\
|\mbox{AdaDetect}_\alpha\cap \cH_1|/m_1&\geq 1-{R}_1(g^\sharp_\cG)-\Delta,\label{highpower}
\end{align}
where $\mbox{AdaDetect}_\alpha$ denotes the rejection set of AdaDetect with score function $\hat{g}$. 
\end{itemize}

\label{th:BHestimated}
Fix any $r\in \{0,\dots,m\}$ and let $\mathcal{R}=\{|\mbox{AdaDetect}^*_\alpha|\geq r\}$. Assume $m\geq 1$, $\l, k\geq 0$, $n=k+\l\geq 1$, and $\ol{G}_0$ \eqref{equGbar} is continuous and strictly decreasing. Under Assumptions~\ref{as:indep} and~\ref{equ-marg}, for any $\delta,\eta\in (0,1)$ such that $ (\ell+1)\delta\alpha(r\vee 1)/m\geq 2$,
\begin{align}\label{powerBONuSstar}
\P\left(\mathcal{R} \cap\{\mbox{AdaDetect}^*_\alpha\subset \mbox{AdaDetect}_{\alpha'}\}^c\right)\leq \P\left(\hat{\eta}> \eta \right) + 2 m e^{-(3/28)  (\ell+1)\delta^2\alpha(r\vee 1)/m},
\end{align}
where $\alpha'=\alpha(1+3\delta)(1+\zeta_r(\eta))$ and $\zeta_r(\cdot)$ and $\hat{\eta}$ are defined in \eqref{funcdelta} and \eqref{diffscore}, respectively.  Furthermore, \eqref{powerBONuSstar} is also true with $\mbox{AdaDetect}^*_\alpha$ replaced by $\BH^*_\alpha$, the BH algorithm applied to the oracle $p$-values $p^*_i=\ol{G}_0(g^*(X_i))$, $1\leq i\leq m$.
